import test from 'node:test';import assert from 'node:assert/strict';import {createRealCadenceQueue} from '../tools/trees/prototype_ordered_real_cadence_queue.mjs';
test('bounded queue preserves interval boundaries, pause ordering and rejects without consuming identity',()=>{const sent=[],q=createRealCadenceQueue('s',x=>sent.push(x),{capacity:3});assert.equal(q.submit({kind:'advance',seconds:.011}).sequence,1);assert.equal(q.submit({kind:'advance',seconds:.031}).sequence,2);assert.equal(q.submit({kind:'pause'}).sequence,3);assert.equal(q.submit({kind:'resume'}).reason,'capacity');assert.equal(sent.length,1);assert.equal(q.acknowledge({session:'stale',sequence:1}).reason,'session');assert.equal(q.acknowledge({session:'s',sequence:2}).reason,'order');assert.equal(q.acknowledge({session:'s',sequence:1}).accepted,true);assert.equal(q.submit({kind:'resume'}).sequence,4);for(let i=2;i<=4;i++)assert.equal(q.acknowledge({session:'s',sequence:i}).accepted,true);assert.deepEqual(sent.map(x=>[x.sequence,x.kind,x.seconds]),[[1,'advance',.011],[2,'advance',.031],[3,'pause',undefined],[4,'resume',undefined]]);assert.equal(q.state().pending.length,0);});
test('invalid intervals and failed transport do not silently discard work',()=>{const q=createRealCadenceQueue('s',()=>{throw Error('transport');});assert.throws(()=>q.submit({kind:'advance',seconds:NaN}),TypeError);assert.equal(q.state().next,1);assert.throws(()=>q.submit({kind:'advance',seconds:.1}),/transport/);assert.equal(q.state().fault,true);assert.equal(q.state().inflight.seconds,.1);assert.equal(q.submit({kind:'pause'}).reason,'fault');});
